package thaumcraft.verification;
import java.nio.file.*;import java.util.*;
import com.google.gson.GsonBuilder;import net.minecraft.client.*;import net.minecraft.client.gui.screens.*;import net.minecraft.client.gui.screens.inventory.*;import net.minecraft.world.*;import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.*;
final class Round3LiveClient {
 static int stage=Integer.getInteger("thaumcraft.round3.start",0),wait,frames;static boolean started,prepared,ready,done;static List<String> captures=new ArrayList<>();static List<Map<String,Object>> observations=new ArrayList<>();
 static final String[] names={"00-node-editor","01-void-armor-runic","02-golem-hud","03-vis-links","04-bore-laser-progress","05-excavation-beam","06-hellbats","07-trunk-eating","08-infernal-book","09-creative-owned-tooltip","10-soap-bubbles","11-status-effect-icons","12-infusion-debug"};
 static void install(net.neoforged.bus.api.IEventBus bus){bus.addListener((net.neoforged.fml.event.lifecycle.FMLClientSetupEvent e)->e.enqueueWork(()->{var mc=Minecraft.getInstance();mc.options.pauseOnLostFocus=false;mc.options.skipMultiplayerWarning=true;mc.options.onboardAccessibility=false;mc.options.save();org.lwjgl.glfw.GLFW.glfwSetWindowAttrib(mc.getWindow().getWindow(),org.lwjgl.glfw.GLFW.GLFW_FOCUS_ON_SHOW,0);org.lwjgl.glfw.GLFW.glfwShowWindow(mc.getWindow().getWindow());}));NeoForge.EVENT_BUS.addListener((ClientTickEvent.Post e)->{try{tick();}catch(Throwable t){fail(t);}});NeoForge.EVENT_BUS.addListener((RenderGuiEvent.Post e)->{if(Minecraft.getInstance().screen==null&&ready&&!done&&++frames>4)try{capture();}catch(Throwable t){fail(t);}});NeoForge.EVENT_BUS.addListener((ScreenEvent.Render.Post e)->{if(ready&&!done&&++frames>4)try{capture();}catch(Throwable t){fail(t);}});}
 static void request()throws Exception{var mc=Minecraft.getInstance();mc.options.keyUse.setDown(false);mc.player.stopUsingItem();mc.setScreen(null);wait=frames=0;prepared=ready=false;Files.writeString(Round3LiveScene.root().resolve("request.json"),Integer.toString(stage));}
 static void tick()throws Exception{var mc=Minecraft.getInstance();if(done||mc.player==null||mc.level==null||mc.getOverlay()!=null)return;if(!started){if(++wait<60)return;started=true;mc.options.fov().set(70);mc.options.guiScale().set(2);mc.options.bobView().set(false);mc.options.gamma().set(.5);mc.options.hideGui=false;mc.resizeDisplay();request();return;}var p=Round3LiveScene.root().resolve("ready.json");if(!Files.exists(p)||Integer.parseInt(Files.readString(p).trim())!=stage)return;wait++;mc.player.setYRot(stage==3?155:stage==4?131:180);mc.player.yRotO=mc.player.getYRot();mc.player.setXRot(stage==3?15:stage==4?4:stage==2?19:stage==12?-12:8);mc.player.xRotO=mc.player.getXRot();mc.player.setDeltaMovement(Vec3.ZERO);
 if(wait>30&&!prepared){prepared=true;switch(stage){
 case 0->{if(!(mc.screen instanceof thaumcraft.client.NodeEditorScreen))throw new AssertionError("node command did not open editor");var inputs=mc.screen.children().stream().filter(w->w instanceof net.minecraft.client.gui.components.EditBox).map(w->(net.minecraft.client.gui.components.EditBox)w).toList();var target=mc.player.pick(64,1,false);if(!(target instanceof BlockHitResult hit)||target.getType()!=HitResult.Type.BLOCK)throw new AssertionError("native target missing");for(var w:mc.screen.children())if(w instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().equals(net.minecraft.network.chat.Component.translatable("thaumcraft.node.feet_position")))button.mouseClicked(button.getX()+8,button.getY()+8,0);if(!inputs.get(0).getValue().equals("0")||!inputs.get(1).getValue().equals("64")||!inputs.get(2).getValue().equals("4"))throw new AssertionError("underfoot coordinates incorrect");observations.add(Map.of("underfoot",List.of(0,64,4)));for(var w:mc.screen.children())if(w instanceof net.minecraft.client.gui.components.Button button&&button.getMessage().equals(net.minecraft.network.chat.Component.translatable("thaumcraft.node.look_position")))button.mouseClicked(button.getX()+8,button.getY()+8,0);if(Integer.parseInt(inputs.get(0).getValue())!=hit.getBlockPos().getX()||Integer.parseInt(inputs.get(1).getValue())!=hit.getBlockPos().getY()||Integer.parseInt(inputs.get(2).getValue())!=hit.getBlockPos().getZ())throw new AssertionError("look coordinates incorrect");observations.add(Map.of("lookTarget",hit.getBlockPos().toString()));for(var widget:mc.screen.children())if(widget instanceof net.minecraft.client.gui.components.EditBox box&&box.getWidth()==40)box.setValue("42");}
 case 1->{mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);thaumcraft.client.RunicShieldHud.accept(new thaumcraft.network.RunicShieldPayload(mc.player.getId(),12,22,false));}
 case 5,6->{mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);}
 case 8->{if(!(mc.screen instanceof thaumcraft.client.ThaumonomiconScreen))throw new AssertionError("book failed to open");var f=mc.screen.getClass().getDeclaredField("selected");f.setAccessible(true);f.set(mc.screen,thaumcraft.network.ClientKnowledge.definitions().get("INFERNALFURNACE"));var spread=mc.screen.getClass().getDeclaredField("spread");spread.setAccessible(true);var pages=mc.screen.getClass().getDeclaredMethod("pages");pages.setAccessible(true);var all=(List<?>)pages.invoke(mc.screen);Files.writeString(Round3LiveScene.root().resolve("book-pages.txt"),all.toString());int index=-1;for(int i=0;i<all.size();i++){var recipe=all.get(i).getClass().getDeclaredMethod("recipe");recipe.setAccessible(true);if(recipe.invoke(all.get(i)).equals("InfernalFurnace"))index=i;}if(index<0)throw new AssertionError("Native book has no infernal construction page");spread.setInt(mc.screen,index/2);observations.add(Map.of("constructionPageIndex",index,"spread",index/2));}
 case 9->{var screen=new CreativeModeInventoryScreen(mc.player,mc.player.connection.enabledFeatures(),true);mc.setScreen(screen);var select=CreativeModeInventoryScreen.class.getDeclaredMethod("selectTab",net.minecraft.world.item.CreativeModeTab.class);select.setAccessible(true);select.invoke(screen,net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("thaumcraft:thaumcraft")));var hovered=AbstractContainerScreen.class.getDeclaredField("hoveredSlot");hovered.setAccessible(true);hovered.set(screen,screen.getMenu().slots.get(45));var tooltip=CreativeModeInventoryScreen.class.getDeclaredMethod("getTooltipFromContainerItem",net.minecraft.world.item.ItemStack.class);tooltip.setAccessible(true);var lines=(List<net.minecraft.network.chat.Component>)tooltip.invoke(screen,mc.player.getMainHandItem());if(lines.stream().map(net.minecraft.network.chat.Component::getString).anyMatch(v->v.toLowerCase().contains("expand")))throw new AssertionError("owned wand retains group tooltip");observations.add(Map.of("ownedWandTooltip",lines.stream().map(net.minecraft.network.chat.Component::getString).toList()));var left=AbstractContainerScreen.class.getDeclaredField("leftPos");var top=AbstractContainerScreen.class.getDeclaredField("topPos");left.setAccessible(true);top.setAccessible(true);var slot=screen.getMenu().slots.get(45);org.lwjgl.glfw.GLFW.glfwSetCursorPos(mc.getWindow().getWindow(),(left.getInt(screen)+slot.x+8)*mc.getWindow().getGuiScale(),(top.getInt(screen)+slot.y+8)*mc.getWindow().getGuiScale());}
 case 11->{mc.setScreen(new InventoryScreen(mc.player));}
 default->{}
 }}
 if(stage!=1)mc.options.setCameraType(CameraType.FIRST_PERSON);
 if(stage==7)for(var entity:mc.level.entitiesForRendering())if(entity instanceof thaumcraft.entities.TravelingTrunk t&&t.lid>0)observations.add(Map.of("chewTick",wait,"lid",t.lid));if(stage==2)for(var entity:mc.level.entitiesForRendering())if(entity instanceof thaumcraft.entities.ThaumicGolem g&&wait<60)observations.add(Map.of("armTick",wait,"timer",g.action()));
 if(stage==10)for(var entity:mc.level.entitiesForRendering())if(entity instanceof net.minecraft.world.entity.monster.Zombie)thaumcraft.client.CleansingParticles.soap((net.minecraft.world.entity.LivingEntity)entity,5);
 if(wait>65){if(stage==6&&java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).noneMatch(e->e instanceof thaumcraft.entities.FocusFireBat))throw new AssertionError("native hellbat focus spawned no bats");ready=true;}
 }
 static void capture()throws Exception{var mc=Minecraft.getInstance();var state=new LinkedHashMap<String,Object>();state.put("stage",stage);state.put("screen",String.valueOf(mc.screen));state.put("target",String.valueOf(mc.hitResult));if(stage==7)for(var e:mc.level.entitiesForRendering())if(e instanceof thaumcraft.entities.TravelingTrunk t){state.put("lid",t.lid);state.put("oldLid",t.oldLid);}if(stage==6)state.put("bats",java.util.stream.StreamSupport.stream(mc.level.entitiesForRendering().spliterator(),false).filter(e->e instanceof thaumcraft.entities.FocusFireBat).count());observations.add(state);String name=names[stage]+".png";mc.renderBuffers().bufferSource().endBatch();try(var img=Screenshot.takeScreenshot(mc.getMainRenderTarget())){img.writeToFile(Round3LiveScene.root().resolve(name));}captures.add(name);if(stage==0&&Boolean.getBoolean("thaumcraft.round3.followup"))stage=7;if(++stage==Integer.getInteger("thaumcraft.round3.end",names.length)){done=true;Files.writeString(Round3LiveScene.root().resolve("result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(Map.of("finished",true,"captures",captures,"observations",observations)));mc.stop();}else request();}
 static void fail(Throwable t){done=true;t.printStackTrace();try{Files.writeString(Round3LiveScene.root().resolve("failure.txt"),t.toString()+" stage="+stage);}catch(Exception ignored){}Minecraft.getInstance().stop();}
}
